/**
 * A member's private reminder on a Coming up date in minutes (#5672 step 2,
 * `spec/behavior/meetings.md` § Reading minutes). A date has no id of its
 * own, so the reminder names it by its day and words as they read when it
 * was set. See `20261120004849_meeting_date_reminders.sql`.
 */
export interface MeetingDateReminder {
  id: string;
  user_id: string;
  chapter_id: string;
  meeting_id: string;
  /** `YYYY-MM-DD`. */
  day: string;
  text: string;
  /** Generated by the database from `text`: never written. */
  text_md5?: string;
  remind_at: string;
  created_at: string;
  updated_at: string;
}
